/* Issue #137 (-exhaustive): since #133 the events after a compare_exchange
 * do not depend on it, so a revisit can keep events of a thread that
 * follow a CAS it deletes or re-reads. When the CAS's outcome changes, it
 * gains or loses its write part and the kept events are no longer where
 * the thread produces them: the replay crashed (a thread that ends where
 * the graph has a kept store). Under -exhaustive -imm the kept events are
 * now moved to their instruction, as under -lkmm (replay keys): 1785
 * executions under every schedule.
 *
 * (Generated by scripts/fuzz-c11.py, seed 821.)
 */
#include <pthread.h>
#include <stdatomic.h>

atomic_int x0;
atomic_int x1;
atomic_int x2;

void *t0(void *arg)
{
	int r0 = 0;
	int r1 = 0;
	atomic_store_explicit(&x0, 0, memory_order_release);
	r1 = 1;
	r0 = atomic_compare_exchange_strong_explicit(&x2, &r1, 1, memory_order_seq_cst, memory_order_acquire);
	atomic_store_explicit(&x2, 1, memory_order_relaxed);
	atomic_store_explicit(&x1, 3, memory_order_release);
	return NULL;
}

void *t1(void *arg)
{
	int r0 = 0;
	atomic_store_explicit(&x1, 2, memory_order_seq_cst);
	r0 = atomic_load_explicit(&x2, memory_order_relaxed);
	return NULL;
}

void *t2(void *arg)
{
	int r0 = 0;
	r0 = atomic_fetch_add_explicit(&x1, 1, memory_order_acq_rel);
	atomic_store_explicit(&x0, 3, memory_order_release);
	return NULL;
}

void *t3(void *arg)
{
	int r0 = 0;
	int r1 = 0;
	int r2 = 0;
	atomic_store_explicit(&x2, 2, memory_order_seq_cst);
	r0 = atomic_fetch_add_explicit(&x1, 1, memory_order_relaxed);
	r2 = 1;
	r1 = atomic_compare_exchange_strong_explicit(&x2, &r2, 2, memory_order_acquire, memory_order_relaxed);
	atomic_store_explicit(&x1, 3, memory_order_relaxed);
	return NULL;
}

int main(void)
{
	pthread_t h0, h1, h2, h3;
	pthread_create(&h0, NULL, t0, NULL);
	pthread_create(&h1, NULL, t1, NULL);
	pthread_create(&h2, NULL, t2, NULL);
	pthread_create(&h3, NULL, t3, NULL);
	pthread_join(h0, NULL);
	pthread_join(h1, NULL);
	pthread_join(h2, NULL);
	pthread_join(h3, NULL);
	return 0;
}
